INSERT INTO toeic_questions (id, part, section, prompt, choices, answer, explanation, grammar_tag, topic) VALUES
(600, 5, 'reading', 'The finance team will ___ the quarterly budget at tomorrow''s meeting.', '["discuss", "discussion", "discussing", "discussed"]', 0, 'Sau "will" dung dong tu nguyen mau: will discuss. EN: After "will", use the base verb: will discuss.', 'tenses', 'finance'),
(601, 5, 'reading', 'Ms. Carter has been working ___ this company since 2018.', '["with", "for", "at", "to"]', 1, '"Work for + cong ty" (lam viec cho...). EN: "Work for + a company" expresses employment.', 'prepositions', 'hr'),
(602, 5, 'reading', 'The new software update will improve system ___ significantly.', '["perform", "performance", "performed", "performing"]', 1, 'Can danh tu sau "system": performance (hieu suat). EN: A noun is needed after "system": performance.', 'word-forms', 'it'),
(603, 5, 'reading', '___ the bad weather, the delivery arrived on schedule.', '["Despite", "Because", "Unless", "Although"]', 0, '"Despite + cum danh tu" dien ta su tuong phan. EN: "Despite + noun phrase" expresses contrast.', 'conjunctions', 'logistics'),
(604, 5, 'reading', 'All visitors are required to register at the front desk ___ entering the building.', '["before", "after", "until", "during"]', 0, 'Dang ky truoc khi vao: before entering. EN: Registration happens first, so "before" fits the logic.', 'prepositions', 'office'),
(605, 5, 'reading', 'The marketing campaign was ___ successful that sales doubled in a month.', '["very", "too", "so", "such"]', 2, 'Cau truc "so + adj + that" (qua... den noi ma...). EN: The structure "so + adjective + that" shows result.', 'conjunctions', 'marketing'),
(606, 5, 'reading', 'Please send the invoice ___ email by Friday afternoon.', '["by", "with", "in", "through"]', 0, '"By email" la cum co dinh chi phuong thuc gui. EN: "By email" is the fixed phrase for the sending method.', 'prepositions', 'finance'),
(607, 5, 'reading', 'The CEO will announce the merger ___ the press conference.', '["during", "at", "on", "for"]', 1, '"At the press conference": su kien dung "at". EN: Events and gatherings take the preposition "at".', 'prepositions', 'meetings'),
(608, 5, 'reading', 'Employees ___ arrive late three times will receive a written warning.', '["whose", "who", "which", "whom"]', 1, 'Menh de quan he chi nguoi lam chu ngu: who. EN: A relative clause for people as subject needs "who".', 'relative-clauses', 'hr'),
(609, 5, 'reading', 'The company''s profits have ___ steadily over the past two years.', '["grown", "growth", "grow", "grows"]', 0, '"Have + V3" (hien tai hoan thanh): have grown. EN: Present perfect needs the past participle: have grown.', 'tenses', 'finance'),
(610, 5, 'reading', 'We need to find a ___ solution to reduce shipping costs.', '["practice", "practical", "practically", "practiced"]', 1, 'Can tinh tu bo nghia "solution": practical (thuc te). EN: An adjective must modify the noun "solution": practical.', 'word-forms', 'logistics'),
(611, 5, 'reading', 'The workshop was postponed ___ the trainer fell ill.', '["because", "despite", "unless", "without"]', 0, 'Chi nguyen nhan truc tiep: because. EN: A direct cause takes "because".', 'conjunctions', 'hr'),
(612, 5, 'reading', 'Customers can return faulty products ___ 30 days of purchase.', '["within", "among", "between", "along"]', 0, '"Within 30 days" (trong vong 30 ngay). EN: "Within + period" means no later than that period.', 'prepositions', 'support'),
(613, 5, 'reading', 'The manager asked the team to complete the report ___ Monday morning.', '["by", "until", "since", "from"]', 0, 'Deadline cham nhat: by Monday morning. EN: A deadline uses "by".', 'prepositions', 'office'),
(614, 5, 'reading', 'Our new branch in Da Nang will open ___ March 1.', '["in", "at", "on", "for"]', 2, 'Ngay cu the (March 1) dung "on". EN: A specific date takes "on".', 'prepositions', 'general'),
(615, 5, 'reading', 'The IT staff fixed the network problem ___ than expected.', '["more quickly", "most quickly", "quick", "quickest"]', 0, 'So sanh hon voi "than": more quickly. EN: A comparison with "than" needs the comparative form.', 'comparatives', 'it'),
(616, 5, 'reading', 'Neither the shipment ___ the documents arrived before noon.', '["or", "nor", "and", "but"]', 1, 'Cap "neither... nor..." (ca... deu khong). EN: "Neither" pairs with "nor".', 'conjunctions', 'logistics'),
(617, 5, 'reading', 'She enjoys ___ in advanced training courses every quarter.', '["participating", "participate", "participation", "participated"]', 0, '"Enjoy + V-ing" (thich lam...). EN: "Enjoy" is followed by a gerund.', 'gerunds', 'hr'),
(618, 5, 'reading', 'The hotel offers free shuttle service ___ the airport every 20 minutes.', '["to", "for", "with", "at"]', 0, 'Dich vu dua don "to the airport" (den san bay). EN: Transport toward a place uses "to".', 'prepositions', 'travel'),
(619, 5, 'reading', 'If we receive the parts today, production ___ resume tomorrow.', '["will", "would", "had", "shall have"]', 0, 'Cau dieu kien loai 1: If + hien tai don, will + V. EN: First conditional: If + present simple, will + verb.', 'conditionals', 'manufacturing'),
(620, 5, 'reading', 'The advertisement attracted ___ than five hundred applicants.', '["much", "more", "most", "many"]', 1, '"More than + so luong" (hon...). EN: "More than + number" expresses a larger quantity.', 'comparatives', 'marketing'),
(621, 5, 'reading', 'Mr. Thompson, ___ oversees the Asian market, will visit Hanoi next week.', '["who", "which", "whose", "whom"]', 0, 'Menh de khong xac dinh chi nguoi, lam chu ngu: who. EN: A non-defining clause for a person as subject uses "who".', 'relative-clauses', 'sales'),
(622, 5, 'reading', 'All electronic devices must be switched off ___ takeoff and landing.', '["during", "while", "until", "since"]', 0, 'Trong suot qua trinh cat/ha canh: during. EN: Throughout a period or process takes "during".', 'prepositions', 'travel'),
(623, 5, 'reading', 'The contract requires both sides to keep pricing information strictly ___.', '["confidential", "confidence", "confidently", "confide"]', 0, 'Can tinh tu sau "keep...": confidential (bao mat). EN: "Keep + object + adjective" needs an adjective: confidential.', 'word-forms', 'contracts'),
(624, 5, 'reading', 'Sales representatives are expected to submit weekly reports ___ Fridays.', '["by", "on", "in", "at"]', 1, 'Ngay trong tuan lap lai dung "on Fridays". EN: Repeated weekdays take "on".', 'prepositions', 'sales'),
(625, 5, 'reading', 'The new policy, ___ takes effect in June, affects all departments.', '["which", "who", "whose", "that where"]', 0, 'Menh de quan he chi vat (policy): which. EN: A relative clause for a thing uses "which".', 'relative-clauses', 'general'),
(626, 5, 'reading', 'We chose this supplier ___ its reliable delivery record.', '["because of", "despite", "instead", "without"]', 0, '"Because of + cum danh tu" chi ly do. EN: "Because of + noun phrase" gives the reason.', 'conjunctions', 'logistics'),
(627, 5, 'reading', 'The technicians are trained to handle customer complaints ___ and politely.', '["professional", "profession", "professionally", "profess"]', 2, 'Can trang tu bo nghia dong tu "handle": professionally. EN: An adverb must modify the verb "handle": professionally.', 'word-forms', 'support'),
(628, 5, 'reading', 'Hardly ___ the presentation begun when the power went out.', '["had", "has", "have", "having"]', 0, 'Dao ngu voi "Hardly": Had + S + V3. EN: Inversion with "Hardly" needs "Had + subject + past participle".', 'tenses', 'meetings'),
(629, 5, 'reading', 'The board approved the proposal ___ minor changes to the timeline.', '["with", "for", "by", "of"]', 0, 'Chap thuan kem dieu chinh nho: with minor changes. EN: Accompanied conditions use "with".', 'prepositions', 'meetings'),
(630, 5, 'reading', 'To apply for the position, please send your CV and a cover letter ___ hr@brightco.example.com.', '["to", "for", "at", "with"]', 0, 'Gui ho so "to" mot dia chi email. EN: Sending something to an address uses "to".', 'prepositions', 'emails'),
(631, 5, 'reading', 'The factory was built ___ meet the growing demand in the region.', '["so as to", "in order", "to", "for"]', 2, 'Chi muc dich ngan gon: to + V (to meet). EN: A short purpose clause uses "to + verb".', 'conjunctions', 'manufacturing'),
(632, 5, 'reading', 'Each participant will receive a certificate of ___ at the end of the course.', '["complete", "completion", "completed", "completing"]', 1, 'Sau "of" can danh tu: completion (su hoan thanh). EN: After "of", use the noun: completion.', 'word-forms', 'hr'),
(633, 5, 'reading', 'The receptionist greeted every guest ___ a warm smile.', '["with", "by", "in", "from"]', 0, 'Chao don kem nu cuoi: with a warm smile. EN: An accompanying manner uses "with".', 'prepositions', 'office'),
(634, 5, 'reading', 'Unless the payment ___ received by Friday, the order will be canceled.', '["is", "was", "were", "has"]', 0, '"Unless" di voi hien tai don trong cau dieu kien. EN: "Unless" pairs with present simple in a conditional.', 'conditionals', 'finance'),
(635, 5, 'reading', 'The data from last quarter shows a sharp ___ in online sales.', '["rise", "raise", "rising", "rose"]', 0, 'Can danh tu sau "a sharp": rise (su tang). EN: After "a sharp", use the noun "rise".', 'vocabulary', 'sales'),
(636, 5, 'reading', 'Passengers ___ connecting flights should go to Terminal 2.', '["with", "for", "of", "to"]', 1, 'Hanh khach co chuyen bay noi chuyen: with connecting flights. EN: Possession or accompaniment uses "with".', 'prepositions', 'travel'),
(637, 5, 'reading', 'The committee will review all applications and notify candidates ___ two weeks.', '["within", "among", "between", "along"]', 0, 'Thong bao trong vong 2 tuan: within two weeks. EN: "Within + period" sets the time limit.', 'prepositions', 'hr'),
(638, 5, 'reading', 'This printer is far ___ reliable than the old model.', '["much", "more", "most", "many"]', 1, '"More reliable than": so sanh hon voi tinh tu dai. EN: A long adjective needs "more ... than" for comparison.', 'comparatives', 'office'),
(639, 5, 'reading', 'He denied ___ the confidential file to anyone outside the team.', '["to send", "sending", "sent", "send"]', 1, '"Deny + V-ing" (phu nhan da lam...). EN: "Deny" is followed by a gerund.', 'gerunds', 'contracts'),
(640, 5, 'reading', 'The annual gala dinner will be held ___ the Grand Palace Hotel.', '["at", "in", "on", "to"]', 0, 'Dia diem to chuc su kien: at the hotel. EN: An event venue takes "at".', 'prepositions', 'meetings'),
(641, 5, 'reading', 'Product samples are available ___ request at the reception desk.', '["upon", "onto", "into", "over"]', 0, 'Cum co dinh "upon request" (khi co yeu cau). EN: "Upon request" is the fixed phrase meaning when asked.', 'vocabulary', 'marketing'),
(642, 5, 'reading', 'The director insisted that the report ___ submitted before noon.', '["be", "is", "was", "has been"]', 0, 'Thuc gia dinh sau "insist that": be + V3. EN: Subjunctive after "insist that" uses the base form: be submitted.', 'subjunctive', 'office'),
(643, 5, 'reading', 'A copy of the signed agreement was mailed to each partner ___ last Friday.', '["no article", "a", "an", "the"]', 0, 'Thieu mao tu truoc "last Friday" (thu 6 tuan truoc). EN: "Last Friday" as a past time marker takes no article.', 'articles', 'contracts'),
(644, 5, 'reading', 'The new shopping mall is located just five minutes ___ the central station.', '["from", "to", "of", "off"]', 0, 'Khoang cach tu mot diem: five minutes from... EN: Distance from a point uses "from".', 'prepositions', 'travel'),
(645, 5, 'reading', '___ it rains tomorrow, the outdoor product launch will move indoors.', '["Should", "Were", "Had", "Would"]', 0, 'Dao ngu dieu kien loai 1: Should + S + V. EN: Inverted first conditional uses "Should + subject + verb".', 'conditionals', 'marketing'),
(646, 5, 'reading', 'All staff members must wear their ID badges ___ all times while on duty.', '["at", "in", "on", "for"]', 0, 'Cum co dinh "at all times" (moi luc). EN: "At all times" is the fixed phrase meaning always.', 'prepositions', 'hr'),
(647, 5, 'reading', 'The research findings were published in a leading ___ journal.', '["science", "scientific", "scientist", "scientifically"]', 1, 'Can tinh tu bo nghia "journal": scientific. EN: An adjective must modify "journal": scientific.', 'word-forms', 'general'),
(648, 5, 'reading', 'Only candidates ___ applications arrive before May 1 will be considered.', '["whose", "who", "which", "whom"]', 0, 'Chi su so huu (don cua ai): whose applications. EN: Possession in a relative clause needs "whose".', 'relative-clauses', 'hr'),
(649, 5, 'reading', 'The courier service guarantees delivery ___ 48 hours across the country.', '["within", "among", "between", "along"]', 0, 'Cam ket trong vong 48 gio: within 48 hours. EN: A guaranteed time limit uses "within".', 'prepositions', 'logistics'),
(650, 5, 'reading', 'The two companies agreed to ___ the costs of the joint survey equally.', '["share", "spend", "lend", "borrow"]', 0, 'Chia se chi phi: share the costs (spend/lend/borrow khong di voi "costs"). EN: Costs borne together use "share"; the others do not collocate with "costs".', 'vocabulary', 'finance'),
(651, 5, 'reading', 'Flight VN213 was delayed ___ heavy fog at Noi Bai Airport.', '["due to", "despite", "instead of", "except"]', 0, 'Nguyen nhan truc tiep (suong mu): due to. EN: A direct cause uses "due to".', 'conjunctions', 'travel'),
(652, 5, 'reading', 'Every desk in the open office has access ___ high-speed internet.', '["to", "for", "with", "of"]', 0, 'Cum co dinh "access to" (quyen truy cap). EN: "Access" pairs with "to".', 'prepositions', 'it'),
(653, 5, 'reading', 'The training manual provides step-by-step ___ for new cashiers.', '["instruct", "instruction", "instructions", "instructive"]', 2, 'Huong dan dang dem duoc so nhieu: instructions. EN: Countable guidance uses the plural noun "instructions".', 'word-forms', 'hr'),
(654, 5, 'reading', 'She has worked in customer service ___ over a decade.', '["for", "since", "during", "from"]', 0, '"For + khoang thoi gian" (over a decade). EN: "For + a period of time" expresses duration.', 'prepositions', 'support'),
(655, 5, 'reading', 'The warehouse stocks were ___ low that production had to pause.', '["very", "too", "so", "such"]', 2, '"So + adj + that" chi ket qua. EN: "So + adjective + that" introduces the result.', 'conjunctions', 'manufacturing'),
(656, 5, 'reading', 'Applicants must be fluent ___ English and Vietnamese.', '["at", "with", "in", "for"]', 2, '"Fluent in + ngon ngu" la cum co dinh. EN: "Fluent in + a language" is the fixed collocation.', 'prepositions', 'hr'),
(657, 5, 'reading', 'The CEO''s speech focused ___ innovation and sustainable growth.', '["on", "in", "at", "for"]', 0, '"Focus on + chu de" (tap trung vao...). EN: "Focus" pairs with "on".', 'prepositions', 'meetings'),
(658, 5, 'reading', 'A 10 percent discount will be applied to all orders ___ this weekend.', '["placed", "placing", "place", "to place"]', 0, 'Rut gon menh de quan he: orders placed (= which are placed). EN: A reduced relative clause uses the past participle: placed.', 'passive', 'sales'),
(659, 5, 'reading', 'The museum will be closed for renovation ___ further notice.', '["until", "by", "since", "during"]', 0, 'Dong cua cho den khi co thong bao moi: until further notice. EN: "Until further notice" is the fixed phrase for an open-ended closure.', 'prepositions', 'general')
